const http=require('node:http'),crypto=require('node:crypto');
const games={horses:['🐎','Corrida de cavalos',['Relâmpago','Trovão','Cometa','Fênix']],formula:['🏎️','Fórmula GP',['Equipe rubra','Equipe azul','Equipe verde','Equipe ouro']],fight:['🥊','Arena de luta',['Ninja','Boxeador','Samurai','Titã']],kart:['🏁','Kart Turbo',['Kart 01','Kart 02','Kart 03','Kart 04']],moto:['🏍️','Moto GP',['Piloto A','Piloto B','Piloto C','Piloto D']],robots:['🤖','Batalha de robôs',['Atlas','Nova','Bolt','Omega']],football:['⚽','Pênaltis',['Azul','Vermelho','Verde','Amarelo']],roulette:['🎡','Roleta',['Vermelho','Preto','Branco']],dice:['🎲','Dados',['Baixo','Sete','Alto']],coin:['🪙','Cara ou coroa',['Cara','Coroa']],cards:['🃏','Duelo de cartas',['Azul','Vermelho','Empate']],wheel:['💎','Roda da sorte',['Ouro','Rubi','Esmeralda','Safira']],slots:['🎰','Trio de símbolos',['Dois iguais','Três iguais','Todos diferentes']],highlow:['🔢','Alto ou baixo',['1–5','6–10']]};
const fs=require('node:fs'),path=require('node:path'),rooms=new Map(),tokens=new Map(),active=new Map(),rng=crypto.randomInt;
const dataFile=process.env.ARCADE_DATA_FILE||path.join(process.cwd(),'royal-arcade-accounts.json');
let accounts=Object.create(null),attempts=new Map();
if(fs.existsSync(dataFile)){let loaded=JSON.parse(fs.readFileSync(dataFile,'utf8'));accounts=Object.assign(Object.create(null),loaded)}
function save(){fs.mkdirSync(path.dirname(dataFile),{recursive:true});let tmp=dataFile+'.tmp';fs.writeFileSync(tmp,JSON.stringify(accounts),{mode:0o600});fs.renameSync(tmp,dataFile)}
let recovered=false;for(let a of Object.values(accounts)){if(a.pending){a.score+=a.pending;a.pending=0;recovered=true}}if(recovered)save();
const validStake=n=>Number.isSafeInteger(n)&&n>=1&&n<=1000000000;
function passwordHash(password,salt){return crypto.scryptSync(password,salt,64).toString('hex')}
function authenticate(req){let id=(req.headers.cookie||'').split(';').map(x=>x.trim()).find(x=>x.startsWith('royal_session='))?.slice(14);let s=tokens.get(id);if(!s||s.until<Date.now()){if(id)tokens.delete(id);return null}return {id,a:accounts[s.key]}}
function session(res,key){let id=crypto.randomBytes(32).toString('hex');tokens.set(id,{key,until:Date.now()+7*86400000});res.setHeader('Set-Cookie','royal_session='+id+'; Path=/; Max-Age=604800; HttpOnly; Secure; SameSite=Strict')}
function accountState(a){let p=active.get(a.key);return p?state(p.r,p):{account:true,room:null,me:{score:a.score,ready:false},name:a.name}}
function rate(req){let key=String(req.headers['x-forwarded-for']||req.socket.remoteAddress).split(',')[0].trim(),n=attempts.get(key)||{count:0,until:Date.now()+600000};if(n.until<Date.now())n={count:0,until:Date.now()+600000};if(++n.count>30)err('Muitas tentativas. Tente mais tarde.',429);attempts.set(key,n)}

const quickWheel=[0,1.2,0,0,1.5,0,1.2,0,0,3,0,0,1.5,0,1.2,0,0,0,10,0];
function quickState(r){let q=r.quick;if(!q)return null;return {id:q.id,kind:q.kind,stake:q.stake,rows:q.rows,done:q.done,payout:q.payout,result:q.result,mult:q.mult,win:q.win}}
function quickResult(r,p,q,payout,win,result,mult){q.done=true;q.payout=payout;q.win=win;q.result=result;q.mult=mult;p.score+=payout;p.account.pending=0;if(win)p.wins++;save()}
function quickPlay(r,p,b){if(!r.solo||r.round)err('Disponível no modo solo, fora da rodada',409);if(b.seq!==(r.quickSeq||0))err('Ação já processada. Atualize o estado.',409);let old=r.quick;if(old&&!old.done)err('Conclua a torre primeiro',409);let stake=b.stake,kind=b.kind;if(!validStake(stake)||stake>p.score)err('Fichas insuficientes ou valor inválido');if(!['dice','wheel','limbo','tower'].includes(kind))err('Jogo inválido');if(kind==='dice'&&(!Number.isInteger(b.target)||b.target<1||b.target>99||!['below','above'].includes(b.side)))err('Alvo inválido');if(kind==='limbo'&&(!Number.isInteger(b.target)||b.target<101||b.target>2000))err('Multiplicador deve ficar entre 1,01 e 20');let q={id:crypto.randomUUID(),kind,stake,rows:[],done:false};r.quick=q;r.quickSeq=(r.quickSeq||0)+1;p.score-=stake;p.account.pending=stake;
if(kind==='tower'){save();return}
if(kind==='dice'){let n=rng(100),chance=b.side==='below'?b.target:100-b.target,win=b.side==='below'?n<b.target:n>=b.target,m=Math.floor(10000/chance)/100;quickResult(r,p,q,win?Math.floor(stake*m):0,win,{number:n,target:b.target,side:b.side,chance},m)}
if(kind==='wheel'){let i=rng(quickWheel.length),m=quickWheel[i];quickResult(r,p,q,Math.floor(stake*m),m>0,{index:i},m)}
if(kind==='limbo'){let m=Math.min(20,Math.floor(100000000/rng(1,1000001))/100),win=m*100+0.00001>=b.target,t=b.target/100;quickResult(r,p,q,win?Math.floor(stake*t):0,win,{number:m,target:t},t)}}
function quickTower(r,p,b){let q=r.quick;if(!r.solo||r.round||!q||q.done||q.kind!=='tower'||q.id!==b.id||b.seq!==(r.quickSeq||0))err('Ação expirada',409);if(b.cash===true){if(!q.rows.length)err('Escolha primeiro uma casa');r.quickSeq++;let m=Math.floor(Math.pow(1.5,q.rows.length)*100)/100;quickResult(r,p,q,Math.floor(q.stake*m),true,{level:q.rows.length,cash:true},m);return}if(!Number.isInteger(b.cell)||b.cell<0||b.cell>2)err('Casa inválida');r.quickSeq++;let bad=rng(3),ok=b.cell!==bad;q.rows.push({cell:b.cell,bad,ok});let m=Math.floor(Math.pow(1.5,q.rows.length)*100)/100;if(!ok)quickResult(r,p,q,0,false,{level:q.rows.length},0);else if(q.rows.length===8)quickResult(r,p,q,Math.floor(q.stake*m),true,{level:8},m);else save()}
function draw(k){let a=games[k][2],order=[...a];for(let i=order.length-1;i>0;i--){let j=rng(i+1);[order[i],order[j]]=[order[j],order[i]]}let winner=order[0],detail=winner+' venceu!';
if(k==='roulette'){let n=rng(37),red=[1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36];winner=n===0?'Branco':red.includes(n)?'Vermelho':'Preto';detail=n+' · '+winner}
if(k==='dice'){let x=rng(1,7),y=rng(1,7);winner=x+y<7?'Baixo':x+y===7?'Sete':'Alto';detail=x+' + '+y+' = '+(x+y)}
if(k==='cards'){let x=rng(1,14),y=rng(1,14);winner=x===y?'Empate':x>y?'Azul':'Vermelho';detail='Azul '+x+' × '+y+' Vermelho'}
if(k==='slots'){let s=['🍒','💎','⭐','7️⃣'],x=Array.from({length:3},()=>s[rng(4)]);winner=new Set(x).size===1?'Três iguais':new Set(x).size===2?'Dois iguais':'Todos diferentes';detail=x.join(' ')}
if(k==='highlow'){let n=rng(1,11);winner=n<=5?'1–5':'6–10';detail=String(n)}
return {winner,detail,order:[winner,...order.filter(x=>x!==winner)]}}
function settle(r){let q=r.round;if(!q||Date.now()<q.end)return;let result=draw(r.game),w=r.players.filter(p=>q.votes[p.id]===result.winner),pot=r.stake*r.players.length;if(r.solo){if(w.length){w[0].score+=r.stake;w[0].wins++}else r.house=(r.house||0)+pot}else if(w.length){let share=Math.floor(pot/w.length);w.forEach((p,i)=>{p.score+=share+(i<pot%w.length?1:0);p.wins++})}else r.house=(r.house||0)+pot;r.last={...result,game:r.game,pot,houseWon:w.length?0:pot,winners:w.map(p=>p.name),id:q.id};r.players.forEach(p=>p.account.pending=0);save();r.history.unshift(r.last);r.history=r.history.slice(0,10);r.round=null;r.players.forEach(p=>p.ready=false)}
function state(r,p){settle(r);p.seen=Date.now();return {account:true,name:p.name,room:r.code,solo:!!r.solo,quick:quickState(r),quickSeq:r.quickSeq||0,house:r.house||0,game:r.game,stake:r.stake,host:r.host===p.id,me:{score:p.score,ready:p.ready},players:r.players.map(x=>({name:x.name,score:x.score,wins:x.wins,ready:x.ready,me:x.id===p.id,host:x.id===r.host,online:Date.now()-x.seen<30000})),round:r.round?{id:r.round.id,end:r.round.end,now:Date.now(),choice:r.round.votes[p.id]||null,votes:Object.keys(r.round.votes).length}:null,last:r.last,history:r.history}}
function leave(r,p){r.players=r.players.filter(x=>x!==p);active.delete(p.id);if(!r.players.length)rooms.delete(r.code);else if(r.host===p.id)r.host=r.players[0].id}
setInterval(()=>{for(let r of rooms.values()){settle(r);if(!r.round)for(let p of [...r.players])if(Date.now()-p.seen>600000){if(r.quick&&!r.quick.done){quickResult(r,p,r.quick,0,false,{level:r.quick.rows.length,expired:true},0)}leave(r,p)}}},1000).unref();
const err=(m,s=400)=>{throw Object.assign(new Error(m),{status:s})};
async function body(req){let b='';for await(let c of req){b+=c;if(b.length>4096)err('Pedido inválido',413)}try{return JSON.parse(b||'{}')}catch{err('JSON inválido')}}
function json(res,s,d){res.writeHead(s,{'content-type':'application/json; charset=utf-8','cache-control':'no-store'});res.end(JSON.stringify(d))}
