function quickOdds(){let msg='';if(quickKind==='dice'){let n=Number($('qTarget').value),p=$('qSide').value==='below'?n:100-n;msg=Number.isInteger(n)&&n>=1&&n<=99?'Chance: '+p+'% · retorno bruto '+(Math.floor(10000/p)/100).toFixed(2)+'x':'Escolha um inteiro de 1 a 99.'}else if(quickKind==='wheel')msg='20 setores iguais: 0x (65%), 1,2x (15%), 1,5x (10%), 3x (5%), 10x (5%).';else if(quickKind==='limbo'){let n=Number($('qTarget').value);msg=n>=1.01&&n<=20?'Chance aproximada: '+(100/n).toFixed(2)+'% · retorno bruto '+n.toFixed(2)+'x':'Alvo entre 1,01x e 20x.'}else msg='8 andares · 2 casas seguras de 3 por andar. Retorno bruto: 1,5x a cada avanço, arredondado para baixo.';$('quickOdds').textContent=msg}
